func:
// Reads and checks the login provider's configuration once, at start, and
// publishes it as global "guardConfig" (plain data, no functions). Every
// other node fails closed while guardConfig.ok is false.
//
// The verifier client is described here, as data: the routes are the same in
// the supported verifier releases, only the body that creates a presentation
// request differs. Adding a release means adding one entry to PROFILES.
const errors = [];
const raw = (k) => String(env.get(k) || '').trim();
const required = (k) => {
    const v = raw(k);
    if (!v) errors.push(k + ' is required');
    return v;
};
const optional = (k, d) => raw(k) || d;
const integer = (k, d, min, max) => {
    const v = optional(k, String(d));
    const n = Number(v);
    if (!/^[0-9]+$/.test(v) || n < min || n > max) {
        errors.push(k + ' must be an integer between ' + min + ' and ' + max);
        return d;
    }
    return n;
};
const list = (k) => raw(k).split(',').map((s) => s.trim()).filter(Boolean);
const baseUrl = (k, v) => {
    if (!v) return '';
    try {
        const u = new url.URL(v);
        if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('scheme');
        return (u.origin + u.pathname).replace(/\/+$/, '');
    } catch (e) {
        errors.push(k + ' must be an http(s) URL');
        return '';
    }
};
const origin = (k, v) => {
    try {
        const u = new url.URL(v);
        if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('scheme');
        return u.origin;
    } catch (e) {
        errors.push(k + ': every entry must be an http(s) origin');
        return null;
    }
};

const attemptTtl = integer('GUARD_ATTEMPT_TTL_SECONDS', 300, 30, 900);

const PROFILES = {
    // Verifier 1.3.x: the client id comes from the tenant's verifier profile.
    'cvs-1.3': () => ({ permissionSet: required('GUARD_VERIFIER_PERMISSION_SET'), ttl: attemptTtl }),
    // Verifier 1.2.x: the request names a presentation policy and the client id.
    'cvs-1.2': () => ({
        presentationPolicyId: required('GUARD_VERIFIER_POLICY_ID'),
        clientId: required('GUARD_VERIFIER_CLIENT_ID'),
        ttl: attemptTtl
    })
};

const api = optional('GUARD_VERIFIER_API', 'cvs-1.3');
let createBody = null;
if (Object.prototype.hasOwnProperty.call(PROFILES, api)) {
    createBody = PROFILES[api]();
} else {
    errors.push('GUARD_VERIFIER_API must be one of ' + Object.keys(PROFILES).join(', '));
}

const tenant = required('GUARD_VERIFIER_TENANT');
if (tenant && !/^[A-Za-z0-9_-]{1,64}$/.test(tenant)) errors.push('GUARD_VERIFIER_TENANT has invalid characters');
const group = optional('GUARD_VERIFIER_GROUP', 'default');
if (!/^[A-Za-z0-9_-]{1,64}$/.test(group)) errors.push('GUARD_VERIFIER_GROUP has invalid characters');
const t = encodeURIComponent(tenant);

const webWallets = [];
if (raw('GUARD_WEB_WALLETS')) {
    let parsed = null;
    try { parsed = JSON.parse(raw('GUARD_WEB_WALLETS')); } catch (e) { parsed = null; }
    if (!Array.isArray(parsed)) {
        errors.push('GUARD_WEB_WALLETS must be a JSON array of {"name", "url"}');
    } else {
        for (const w of parsed) {
            const ok = w && typeof w.name === 'string' && w.name.trim() && typeof w.url === 'string' &&
                /^https:\/\//.test(w.url) && (w.url.includes('{request_uri}') || w.url.includes('{openid4vp}'));
            if (ok) webWallets.push({ name: w.name.trim().slice(0, 60), url: w.url });
            else errors.push('GUARD_WEB_WALLETS: each entry needs a name and an https url with {request_uri} or {openid4vp}');
        }
    }
}

const statusListOrigins = list('GUARD_STATUS_LIST_ORIGINS').map((o) => origin('GUARD_STATUS_LIST_ORIGINS', o)).filter(Boolean);
if (statusListOrigins.length === 0) errors.push('GUARD_STATUS_LIST_ORIGINS is required (the status list origins of the trusted issuers)');

const firstPartyClients = list('GUARD_FIRST_PARTY_CLIENTS');
if (firstPartyClients.length === 0) errors.push('GUARD_FIRST_PARTY_CLIENTS is required');

const cfg = {
    ok: false,
    errors,
    hydraAdmin: baseUrl('GUARD_HYDRA_ADMIN_URL', required('GUARD_HYDRA_ADMIN_URL')),
    policyUrl: baseUrl('GUARD_POLICY_URL', required('GUARD_POLICY_URL')),
    verifier: {
        api,
        base: baseUrl('GUARD_VERIFIER_URL', required('GUARD_VERIFIER_URL')),
        tenant,
        group,
        createBody,
        createPath: '/v1/tenants/' + t + '/internal/presentations/authorization',
        requestObjectPath: '/v1/tenants/' + t + '/presentation/proof/{state}/request-object/request.jwt',
        recordPath: '/v1/tenants/' + t + '/internal/presentations/{state}',
        pendingCodes: [404, 409],
        verifiedStatus: 'presentation-received'
    },
    firstPartyClients,
    statusListOrigins,
    webWallets,
    attemptTtl,
    lockout: {
        maxFailures: integer('GUARD_LOCKOUT_MAX_FAILURES', 5, 1, 100),
        windowSeconds: integer('GUARD_LOCKOUT_WINDOW_SECONDS', 900, 60, 86400),
        seconds: integer('GUARD_LOCKOUT_SECONDS', 900, 60, 86400)
    },
    proxyHops: integer('GUARD_TRUSTED_PROXY_HOPS', 1, 0, 5)
};
cfg.ok = errors.length === 0;

global.set('guardConfig', cfg);
if (cfg.ok) {
    node.status({ fill: 'green', shape: 'dot', text: 'verifier ' + api });
} else {
    node.status({ fill: 'red', shape: 'ring', text: errors.length + ' configuration error(s)' });
    node.error('guard configuration invalid, logins are refused: ' + errors.join('; '));
}
return msg;   // no outputs: nothing is sent, the node just ends

// GET /guard/login?login_challenge=... — the authorization server sends the
// browser here. Checks the challenge, the configuration and the lockout of
// the client address, then asks the authorization server's admin API for the
// login request.
// Outputs: 1 = admin API request, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
if (!cfg || !cfg.ok) {
    return fail(503, 'Login unavailable', 'The login service is not configured. Contact the platform administrator.');
}

const challenge = String((msg.req.query || {}).login_challenge || '');
if (!/^[A-Za-z0-9._~-]{1,512}$/.test(challenge)) {
    return fail(400, 'Invalid login request', 'Start the login again from the application.');
}

// Client address: with N trusted proxies (the ingress), the client is the
// N-th entry from the right of X-Forwarded-For; entries further left are
// set by the client and are not trusted.
const xff = String((msg.req.headers || {})['x-forwarded-for'] || '')
    .split(',').map((s) => s.trim()).filter(Boolean);
const addr = (cfg.proxyHops > 0 && xff.length >= cfg.proxyHops)
    ? xff[xff.length - cfg.proxyHops]
    : (msg.req.ip || 'unknown');

const now = Date.now();
const locks = flow.get('guardLockouts') || {};
const lock = locks['addr:' + addr];
if (lock && lock.until > now) {
    node.log(JSON.stringify({ event: 'guard.login.locked', key: 'addr', until: new Date(lock.until).toISOString() }));
    return fail(429, 'Too many failed attempts', 'Logins from this address are paused for a while. Try again later or contact the platform administrator.');
}

msg._guard = { challenge, addr };
msg.method = 'GET';
msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/login?login_challenge=' + encodeURIComponent(challenge);
msg.headers = { accept: 'application/json' };
msg.payload = '';
return [msg, null];

// Reply of the authorization server to GET .../requests/login. Only the
// first-party web applications may use the wallet login. Then asks the
// verifier to create a presentation request (body per verifier release, see
// guard-config).
// Outputs: 1 = verifier request, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
if (!cfg || !cfg.ok) {
    return fail(503, 'Login unavailable', 'The login service is not configured. Contact the platform administrator.');
}
const lr = msg.payload;
if (msg.statusCode !== 200 || !lr || typeof lr !== 'object') {
    // 404/410: unknown or expired challenge; anything else: admin API down
    const expired = msg.statusCode === 404 || msg.statusCode === 410;
    return fail(expired ? 410 : 502, expired ? 'Login request expired' : 'Login unavailable',
        expired ? 'Start the login again from the application.' : 'The authorization server did not answer. Try again later.');
}
const clientId = lr.client && typeof lr.client.client_id === 'string' ? lr.client.client_id : '';
if (!cfg.firstPartyClients.includes(clientId)) {
    node.log(JSON.stringify({ event: 'guard.login.refused', reason: 'client not allowed', client_id: clientId }));
    return fail(403, 'Application not allowed', 'This application may not use the wallet login.');
}

msg._guard.appClient = clientId;
const v = cfg.verifier;
msg.method = 'POST';
msg.url = v.base + v.createPath;
msg.headers = { 'content-type': 'application/json', accept: 'application/json', 'x-tenantId': v.tenant, 'x-groupid': v.group };
msg.payload = JSON.stringify(v.createBody);
return [msg, null];

// Reply of the verifier to the create call: {presentationId, requestId,
// authorizationUrl, requestUri, ttl} in both supported releases. Then fetches
// the request object, which carries the nonce, the verifier's client id and
// the DCQL query ids that the stored presentation is checked against.
// Outputs: 1 = request object fetch, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
const p = msg.payload;
const str = (x) => typeof x === 'string' && x.length > 0 && x.length < 4096;
if ((msg.statusCode !== 201 && msg.statusCode !== 200) || !p || typeof p !== 'object' ||
    !str(p.presentationId) || !str(p.requestId) || !str(p.authorizationUrl) ||
    !p.authorizationUrl.startsWith('openid4vp://')) {
    node.log(JSON.stringify({ event: 'guard.verifier.error', step: 'create', http: msg.statusCode }));
    return fail(502, 'Login unavailable', 'The credential verifier could not create the request. Try again later.');
}

msg._guard.state = p.presentationId;
msg._guard.requestId = p.requestId;
msg._guard.link = p.authorizationUrl;
msg._guard.requestUri = str(p.requestUri) ? p.requestUri : '';

const v = cfg.verifier;
msg.method = 'GET';
msg.url = v.base + v.requestObjectPath.replace('{state}', encodeURIComponent(p.presentationId));
msg.headers = { accept: 'application/oauth-authz-req+jwt, application/jwt', 'x-tenantId': v.tenant, 'x-groupid': v.group };
msg.payload = '';
return [msg, null];

// Request object fetched: records the login attempt (single use, expires
// after GUARD_ATTEMPT_TTL_SECONDS) and serves the login page. The page shows
// the request as a QR code (mobile wallet), as a link (wallet on the same
// device) and as one button per configured web wallet (redirect), then polls
// /guard/login/status until the attempt ends.
// libs: crypto, qrcode. Outputs: 1 = login page, 2 = error page.
const cfg = global.get('guardConfig');
const g = msg._guard || {};
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    node.send([null, msg]);
};

let ro = null;
try {
    const parts = String(msg.payload || '').trim().split('.');
    if (msg.statusCode === 200 && parts.length === 3) {
        ro = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    }
} catch (e) {
    ro = null;
}
const dcql = ro && ro.dcql_query && Array.isArray(ro.dcql_query.credentials) ? ro.dcql_query.credentials : [];
const dcqlIds = dcql.map((q) => (q && typeof q.id === 'string' ? q.id : null)).filter(Boolean);
if (!ro || typeof ro.nonce !== 'string' || !ro.nonce || typeof ro.client_id !== 'string' || !ro.client_id || dcqlIds.length === 0) {
    node.log(JSON.stringify({ event: 'guard.verifier.error', step: 'request-object', http: msg.statusCode }));
    fail(502, 'Login unavailable', 'The credential verifier returned an unusable request. Try again later.');
    return null;
}

const now = Date.now();
const attempts = flow.get('guardAttempts') || {};
for (const [k, a] of Object.entries(attempts)) {
    // drop expired attempts, and supersede the earlier attempts of the same
    // login request (renewing the attempt replaces it)
    if (a.expires + 60000 < now || (a.challenge === g.challenge && a.status === 'pending')) delete attempts[k];
}
const id = crypto.randomBytes(32).toString('hex');
attempts[id] = {
    challenge: g.challenge,
    appClient: g.appClient,
    addr: g.addr,
    state: g.state,
    requestId: g.requestId,
    nonce: ro.nonce,
    verifierClientId: ro.client_id,
    dcqlIds,
    created: now,
    expires: now + cfg.attemptTtl * 1000,
    status: 'pending',
    busy: false
};
flow.set('guardAttempts', attempts);

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const requestUri = g.requestUri || (() => {
    try { return new url.URL(g.link.replace(/^openid4vp:\/\//, 'https://x/')).searchParams.get('request_uri') || ''; } catch (e) { return ''; }
})();
const wallets = cfg.webWallets.map((w) => ({
    name: w.name,
    href: w.url
        .split('{openid4vp}').join(encodeURIComponent(g.link))
        .split('{request_uri}').join(encodeURIComponent(requestUri))
        .split('{client_id}').join(encodeURIComponent(ro.client_id))
}));
const scriptNonce = crypto.randomBytes(16).toString('base64');

(async () => {
    let qr = '';
    try {
        qr = await qrcode.toString(g.link, { type: 'svg', errorCorrectionLevel: 'M', margin: 1 });
    } catch (e) {
        qr = '';
    }
    const walletButtons = wallets.length
        ? '<h2>Use a web wallet</h2><ul class="wallets">' +
          wallets.map((w) => '<li><a class="button" href="' + esc(w.href) + '">Open ' + esc(w.name) + '</a></li>').join('') + '</ul>'
        : '';
    msg.statusCode = 200;
    msg.headers = {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'no-store',
        'referrer-policy': 'no-referrer',
        'x-frame-options': 'DENY',
        'content-security-policy': "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; " +
            "script-src 'nonce-" + scriptNonce + "'; connect-src 'self'; form-action 'none'; frame-ancestors 'none'; base-uri 'none'"
    };
    delete msg.cookies;
    msg.payload = '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
        '<meta name="viewport" content="width=device-width, initial-scale=1"><title>Log in with your wallet</title>' +
        '<style>body{font-family:system-ui,sans-serif;max-width:32rem;margin:2rem auto;padding:0 1rem;color:#1b1f24}' +
        'h1{font-size:1.4rem}h2{font-size:1.05rem;margin-top:1.6rem}.qr svg{width:16rem;height:16rem}' +
        '.button{display:inline-block;padding:.55rem 1rem;border:1px solid #1b1f24;border-radius:.4rem;color:inherit;text-decoration:none}' +
        '.wallets{list-style:none;padding:0}.wallets li{margin:.4rem 0}#state{margin-top:1.6rem;min-height:1.5rem}' +
        '@media (prefers-color-scheme:dark){body{background:#14171a;color:#e6e8ea}.button{border-color:#e6e8ea}.qr svg{background:#fff}}</style>' +
        '</head><body><h1>Log in with your wallet</h1>' +
        '<p>Present your role credential to log in. The request expires in ' + Math.round(cfg.attemptTtl / 60) + ' minutes and can be used once.</p>' +
        '<h2>Scan with a mobile wallet</h2>' +
        (qr ? '<div class="qr" aria-label="QR code of the presentation request">' + qr + '</div>' : '') +
        '<p><a class="button" href="' + esc(g.link) + '">Open a wallet on this device</a></p>' +
        walletButtons +
        '<p id="state" role="status">Waiting for your wallet…</p>' +
        '<p><a id="renew" class="button" href="" hidden>Start again</a></p>' +
        '<script nonce="' + scriptNonce + '">(function(){var id="' + id + '";var s=document.getElementById("state");' +
        'var r=document.getElementById("renew");r.href=location.href;' +
        'function show(t,renew){s.textContent=t;r.hidden=!renew;}' +
        'function poll(){fetch("login/status?attempt="+id,{cache:"no-store"}).then(function(x){return x.json();}).then(function(d){' +
        'if(d.state==="done"&&d.redirect_to){s.textContent="Logged in, redirecting…";location.assign(d.redirect_to);return;}' +
        'if(d.state==="refused"){show(d.message||"The login was refused.",true);return;}' +
        'if(d.state==="expired"||d.state==="unknown"){show("This request has expired.",true);return;}' +
        'if(d.state==="error"){show("The login could not be completed. Try again later.",true);return;}' +
        'setTimeout(poll,2000);}).catch(function(){setTimeout(poll,4000);});}setTimeout(poll,2000);})();</script>' +
        '</body></html>';
    node.log(JSON.stringify({ event: 'guard.login.started', client_id: g.appClient }));
    node.send([msg, null]);
})();
return null;

// Renders msg._guardError {code, title, text} as a plain page, with no
// internal detail.
// Outputs: 1 = page.
const e = msg._guardError || { code: 500, title: 'Login unavailable', text: 'Try again later.' };
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
msg.statusCode = Number.isInteger(e.code) ? e.code : 500;
msg.headers = {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
    'x-frame-options': 'DENY',
    'content-security-policy': "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'"
};
delete msg.cookies;
msg.payload = '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(e.title) + '</title>' +
    '<style>body{font-family:system-ui,sans-serif;max-width:32rem;margin:2rem auto;padding:0 1rem;color:#1b1f24}' +
    '@media (prefers-color-scheme:dark){body{background:#14171a;color:#e6e8ea}}</style></head>' +
    '<body><h1>' + esc(e.title) + '</h1><p>' + esc(e.text) + '</p></body></html>';
return msg;

// GET /guard/login/status?attempt=... — polled by the login page. Answers
// from the attempt when it has ended; otherwise asks the verifier for the
// presentation it stored for this attempt's request.
// Outputs: 1 = verifier record fetch, 2 = JSON answer.
const cfg = global.get('guardConfig');
const answer = (code, body) => {
    msg.statusCode = code;
    msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
    delete msg.cookies;
    msg.payload = body;
    return [null, msg];
};
if (!cfg || !cfg.ok) return answer(503, { state: 'error' });

const id = String((msg.req.query || {}).attempt || '');
if (!/^[0-9a-f]{64}$/.test(id)) return answer(400, { state: 'unknown' });
const attempts = flow.get('guardAttempts') || {};
const a = attempts[id];
if (!a) return answer(404, { state: 'unknown' });

if (a.status === 'done') return answer(200, { state: 'done', redirect_to: a.redirectTo });
if (a.status === 'refused') return answer(200, { state: 'refused', message: a.message });
if (a.status === 'error') return answer(200, { state: 'error' });
if (Date.now() > a.expires) {
    a.status = 'expired';
    flow.set('guardAttempts', attempts);
    return answer(200, { state: 'expired' });
}
if (a.status === 'expired') return answer(200, { state: 'expired' });
// one evaluation at a time per attempt: a concurrent poll just waits
if (a.busy) return answer(200, { state: 'pending' });
a.busy = true;
flow.set('guardAttempts', attempts);

msg._guard = { attemptId: id };
const v = cfg.verifier;
msg.method = 'GET';
msg.url = v.base + v.recordPath.replace('{state}', encodeURIComponent(a.state));
msg.headers = { accept: 'application/json', 'x-tenantId': v.tenant, 'x-groupid': v.group };
msg.payload = '';
return [msg, null];

// The verifier's stored presentation for this attempt. The verifier checks
// the signatures, the nonce and the audience; this node checks again what
// binds the presentation to this attempt and to its holder, from the stored
// record only (never from what the wallet answered):
//   - the record is verified and belongs to this attempt's request;
//   - it answers this request's DCQL query ids, and nothing else;
//   - the presentation's nonce and audience are this request's;
//   - holder binding: the presentation is signed by the credential subject;
//   - one role credential with an organisation DID and roles;
//   - the credential carries a status entry on an allowed status list origin.
// Supports JSON presentations (ldp_vp) and JWT presentations (jwt_vp_json);
// any other format is refused.
// Outputs: 1 = status list fetch, 2 = refusal, 3 = JSON answer (pending/error).
const cfg = global.get('guardConfig');
const attempts = flow.get('guardAttempts') || {};
const id = (msg._guard || {}).attemptId;
const a = attempts[id];
const answer = (code, body) => {
    if (a) { a.busy = false; flow.set('guardAttempts', attempts); }
    msg.statusCode = code;
    msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
    delete msg.cookies;
    msg.payload = body;
    return [null, null, msg];
};
const refuse = (reason, counts) => {
    msg._guard.refusal = { reason, countsAsFailure: counts !== false };
    return [null, msg, null];
};
if (!cfg || !cfg.ok || !a) return answer(503, { state: 'error' });

if (cfg.verifier.pendingCodes.includes(msg.statusCode)) return answer(200, { state: 'pending' });
if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== 'object') {
    node.log(JSON.stringify({ event: 'guard.verifier.error', step: 'record', http: msg.statusCode }));
    return answer(200, { state: 'pending' });
}
const rec = msg.payload;
const eq = (x, y) => typeof x === 'string' && typeof y === 'string' && x.length === y.length &&
    crypto.timingSafeEqual(Buffer.from(x), Buffer.from(y));
const didOf = (ref) => (typeof ref === 'string' ? ref.split('#')[0] : (ref && typeof ref.id === 'string' ? ref.id.split('#')[0] : null));
const jwtPayload = (s) => {
    if (typeof s !== 'string') return null;
    const parts = s.trim().split('.');
    if (parts.length !== 3) return null;
    try { const p = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8')); return p && typeof p === 'object' ? p : null; } catch (e) { return null; }
};
const asJson = (v) => {
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    if (typeof v === 'string' && v.trim().startsWith('{')) {
        try { const o = JSON.parse(v); return o && typeof o === 'object' ? o : null; } catch (e) { return null; }
    }
    return null;
};

if (rec.status !== cfg.verifier.verifiedStatus) return refuse('presentation not verified by the verifier');
if (!eq(rec.requestId, a.requestId)) return refuse('presentation belongs to another request');
const pres = rec.presentation;
if (!pres || typeof pres !== 'object' || Array.isArray(pres) || Object.keys(pres).length === 0) return refuse('no presentation in the verifier record');
const keys = Object.keys(pres);
if (!keys.every((k) => a.dcqlIds.includes(k))) return refuse('presentation answers queries outside this request');

// Normalise every presented VP into {nonce, aud, holder, vcs: [{issuer, subject, status, exp, nbf}]}
const vps = [];
for (const k of keys) {
    const entries = Array.isArray(pres[k]) ? pres[k] : [pres[k]];
    for (const e of entries) {
        const j = jwtPayload(e);
        if (j && j.vp) {
            const vcs = (Array.isArray(j.vp.verifiableCredential) ? j.vp.verifiableCredential : [j.vp.verifiableCredential]).map((c) => {
                const cj = jwtPayload(c);
                if (cj && cj.vc) {
                    const subj = Array.isArray(cj.vc.credentialSubject) ? cj.vc.credentialSubject[0] : cj.vc.credentialSubject;
                    return { issuer: didOf(cj.iss || cj.vc.issuer), subject: Object.assign({}, subj, { id: (subj && subj.id) || cj.sub }),
                        status: cj.vc.credentialStatus, exp: cj.exp, nbf: cj.nbf };
                }
                return null;
            });
            vps.push({ nonce: j.nonce, aud: j.aud, holder: didOf(j.iss || j.vp.holder), vcs });
            continue;
        }
        const o = asJson(e);
        if (o && o.proof) {
            const proofs = Array.isArray(o.proof) ? o.proof : [o.proof];
            const p0 = proofs[0] || {};
            const vcs = (Array.isArray(o.verifiableCredential) ? o.verifiableCredential : [o.verifiableCredential]).map((c) => {
                const co = asJson(c);
                if (!co) return null;
                const subj = Array.isArray(co.credentialSubject) ? co.credentialSubject[0] : co.credentialSubject;
                const exp = co.validUntil || co.expirationDate;
                return { issuer: didOf(co.issuer), subject: subj, status: co.credentialStatus,
                    exp: exp ? Math.floor(Date.parse(exp) / 1000) : undefined };
            });
            vps.push({ nonce: p0.challenge, aud: p0.domain || p0.audience, holder: didOf(o.holder || p0.verificationMethod),
                signer: didOf(p0.verificationMethod), vcs });
            continue;
        }
        return refuse('presentation format not supported');
    }
}

let role = null;
const nowS = Math.floor(Date.now() / 1000);
for (const vp of vps) {
    if (!eq(vp.nonce, a.nonce)) return refuse('presentation nonce does not match this request');
    const audOk = Array.isArray(vp.aud) ? vp.aud.some((x) => eq(x, a.verifierClientId)) : eq(vp.aud, a.verifierClientId);
    if (!audOk) return refuse('presentation audience does not match this request');
    if (!vp.holder || (vp.signer && !eq(vp.signer, vp.holder))) return refuse('presentation holder is not its signer');
    for (const vc of vp.vcs) {
        if (!vc || !vc.subject || typeof vc.subject !== 'object') return refuse('presented credential not readable');
        if (!eq(vc.subject.id, vp.holder)) return refuse('holder binding: credential subject is not the presenter');
        if (typeof vc.exp === 'number' && vc.exp < nowS) return refuse('presented credential expired');
        if (typeof vc.nbf === 'number' && vc.nbf > nowS + 60) return refuse('presented credential not yet valid');
        if (!role && typeof vc.subject.org_did === 'string' && Array.isArray(vc.subject.roles)) role = { vc, holder: vp.holder };
    }
}
if (!role) return refuse('no role credential presented');

// holder lockout (the address lockout was checked when the attempt started)
const locks = flow.get('guardLockouts') || {};
const hl = locks['holder:' + role.holder];
if (hl && hl.until > Date.now()) return refuse('holder locked out after repeated failures', false);

// status entry: Bitstring Status List or Token Status List shape
const st = Array.isArray(role.vc.status) ? role.vc.status : (role.vc.status ? [role.vc.status] : []);
if (st.length !== 1) return refuse('credential must carry exactly one status entry');
const s0 = st[0];
const ref = s0.statusListCredential || (s0.status_list && s0.status_list.uri);
const idx = s0.statusListCredential ? s0.statusListIndex : (s0.status_list && s0.status_list.idx);
const index = typeof idx === 'number' ? idx : (/^[0-9]{1,9}$/.test(String(idx)) ? Number(idx) : -1);
let statusUrl = null;
try { statusUrl = new url.URL(String(ref)); } catch (e) { statusUrl = null; }
if (!statusUrl || index < 0) return refuse('credential status entry not readable');
if (!cfg.statusListOrigins.includes(statusUrl.origin)) return refuse('credential status list origin not allowed');

msg._guard.holder = role.holder;
msg._guard.credential = {
    issuer: role.vc.issuer,
    org_did: role.vc.subject.org_did,
    roles: role.vc.subject.roles.filter((r) => typeof r === 'string'),
    purpose: Array.isArray(role.vc.subject.purposes) ? role.vc.subject.purposes.filter((p) => typeof p === 'string') : [],
    name: typeof role.vc.subject.name === 'string' ? role.vc.subject.name : undefined,
    email: typeof role.vc.subject.email === 'string' ? role.vc.subject.email : undefined
};
msg._guard.statusIndex = index;
msg.method = 'GET';
msg.url = statusUrl.href;
msg.headers = { accept: 'application/vnd.xfsc.status-list, application/statuslist+jwt, application/vc+jwt, application/json' };
msg.payload = '';
return [msg, null, null];

// The status list of the presented credential. Accepted shapes:
//   - W-Stack status service: {"list": base64url(zlib)}, bit index 0 is the
//     left-most bit of byte 0 (as in the W3C Bitstring Status List);
//   - W3C Bitstring Status List credential (JSON or JWT): credentialSubject.
//     encodedList = multibase "u" + base64url(gzip), same bit order;
//   - IETF Token Status List (JWT): status_list {bits, lst = base64url(zlib)},
//     entries read from the least significant bit.
// Any error, a missing list or an index beyond it refuses the login (the
// credential's non-revocation cannot be shown). Then asks the policy engine.
// libs: zlib. Outputs: 1 = policy request, 2 = refusal.
const cfg = global.get('guardConfig');
const g = msg._guard || {};
const attempts = flow.get('guardAttempts') || {};
const a = attempts[g.attemptId];
const refuse = (reason, counts) => {
    g.refusal = { reason, countsAsFailure: counts !== false };
    return [null, msg];
};
if (!cfg || !cfg.ok || !a) return refuse('configuration or attempt missing', false);
if (msg.statusCode !== 200) return refuse('credential status list unavailable', false);

const jwtPayload = (s) => {
    const parts = String(s).trim().split('.');
    if (parts.length !== 3) return null;
    try { return JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8')); } catch (e) { return null; }
};
let body = msg.payload;
if (Buffer.isBuffer(body)) body = body.toString('utf8');
let doc = null;
if (typeof body === 'string') {
    const t = body.trim();
    if (t.startsWith('{')) { try { doc = JSON.parse(t); } catch (e) { doc = null; } } else { doc = jwtPayload(t); }
} else if (body && typeof body === 'object') {
    doc = body;
}
if (!doc || typeof doc !== 'object') return refuse('credential status list not readable', false);

let bytes = null;
let bits = 1;
let lsbFirst = false;
try {
    const subj = (doc.vc && doc.vc.credentialSubject) || doc.credentialSubject;
    if (typeof doc.list === 'string') {
        bytes = zlib.unzipSync(Buffer.from(doc.list, 'base64url'));
    } else if (subj && typeof subj.encodedList === 'string') {
        const enc = subj.encodedList.startsWith('u') ? subj.encodedList.slice(1) : subj.encodedList;
        bytes = zlib.unzipSync(Buffer.from(enc, 'base64url'));
    } else if (doc.status_list && typeof doc.status_list.lst === 'string') {
        bits = Number(doc.status_list.bits);
        if (![1, 2, 4, 8].includes(bits)) return refuse('credential status list not readable', false);
        bytes = zlib.unzipSync(Buffer.from(doc.status_list.lst, 'base64url'));
        lsbFirst = true;
    }
} catch (e) {
    bytes = null;
}
if (!bytes) return refuse('credential status list not readable', false);

const index = g.statusIndex;
const bitPos = index * bits;
const byteAt = Math.floor(bitPos / 8);
if (!Number.isInteger(index) || index < 0 || byteAt >= bytes.length) return refuse('credential status index outside the list', false);
const shift = lsbFirst ? (bitPos % 8) : (8 - bits - (bitPos % 8));
const value = (bytes[byteAt] >> shift) & ((1 << bits) - 1);
if (value !== 0) return refuse('credential revoked or suspended');

msg.method = 'POST';
msg.url = cfg.policyUrl;
msg.headers = { 'content-type': 'application/json', accept: 'application/json' };
msg.payload = JSON.stringify({
    input: {
        org_did: g.credential.org_did,
        roles: g.credential.roles,
        issuer: g.credential.issuer,
        client_id: a.appClient
    }
});
return [msg, null];

// Decision of the policy engine (facis.login). On allow, accepts the login at
// the authorization server: the subject is the holder DID, the verified
// claims travel in the login context to the consent step, which puts them
// into the tokens. Nothing is remembered: every login presents again.
// Outputs: 1 = accept login request, 2 = refusal.
const cfg = global.get('guardConfig');
const g = msg._guard || {};
const attempts = flow.get('guardAttempts') || {};
const a = attempts[g.attemptId];
const refuse = (reason, counts) => {
    g.refusal = { reason, countsAsFailure: counts !== false };
    return [null, msg];
};
if (!cfg || !cfg.ok || !a) return refuse('configuration or attempt missing', false);

let body = msg.payload;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
if (msg.statusCode !== 200 || !body || typeof body !== 'object' || !('result' in body)) {
    node.log(JSON.stringify({ event: 'guard.policy.error', http: msg.statusCode }));
    return refuse('policy engine unavailable', false);
}
// facis.login returns {allow, reason}; a plain boolean is accepted too
const d = body.result;
const allow = d === true || (d && typeof d === 'object' && d.allow === true);
if (!allow) return refuse('login policy: ' + (d && typeof d.reason === 'string' ? d.reason : 'denied'));

const c = g.credential;
const claims = { org_did: c.org_did, roles: c.roles, purpose: c.purpose };
const display = {};
if (c.name) display.name = c.name;
if (c.email) display.email = c.email;

msg.method = 'PUT';
msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/login/accept?login_challenge=' + encodeURIComponent(a.challenge);
msg.headers = { 'content-type': 'application/json', accept: 'application/json' };
msg.payload = JSON.stringify({
    subject: g.holder,
    remember: false,
    amr: ['vp'],
    context: { claims, display, issuer: c.issuer }
});
return [msg, null];

// Reply of the authorization server to the login accept: {redirect_to}. The
// attempt ends; the login page follows redirect_to, and the authorization
// server continues with the consent step.
// Outputs: 1 = JSON answer.
const g = msg._guard || {};
const attempts = flow.get('guardAttempts') || {};
const a = attempts[g.attemptId];
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
delete msg.cookies;
const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
if (!a) {
    msg.statusCode = 404;
    msg.payload = { state: 'unknown' };
    return msg;
}
a.busy = false;
if (msg.statusCode === 200 && typeof p.redirect_to === 'string' && /^https?:\/\//.test(p.redirect_to)) {
    a.status = 'done';
    a.redirectTo = p.redirect_to;
    flow.set('guardAttempts', attempts);
    node.log(JSON.stringify({ event: 'guard.login.accepted', client_id: a.appClient, org_did: g.credential && g.credential.org_did }));
    msg.statusCode = 200;
    msg.payload = { state: 'done', redirect_to: a.redirectTo };
    return msg;
}
a.status = 'error';
flow.set('guardAttempts', attempts);
node.log(JSON.stringify({ event: 'guard.login.error', step: 'accept', http: msg.statusCode }));
msg.statusCode = 200;
msg.payload = { state: 'error' };
return msg;

// Every refusal of a login attempt ends here. The attempt ends (single use).
// A refusal caused by the presentation counts as a failure for the client
// address and for the holder; after GUARD_LOCKOUT_MAX_FAILURES failures
// within GUARD_LOCKOUT_WINDOW_SECONDS, both are locked out for
// GUARD_LOCKOUT_SECONDS. Failures of the platform (verifier, status list or
// policy engine unavailable) do not count. The page gets a generic message;
// the reason goes to the audit log only.
// Outputs: 1 = JSON answer.
const cfg = global.get('guardConfig');
const g = msg._guard || {};
const r = g.refusal || { reason: 'refused', countsAsFailure: true };
const attempts = flow.get('guardAttempts') || {};
const a = attempts[g.attemptId];
const now = Date.now();
let locked = false;

if (a) {
    a.busy = false;
    a.status = 'refused';
    a.message = 'The login was refused. Check that you presented a valid role credential for this application.';
    flow.set('guardAttempts', attempts);
}
if (cfg && cfg.ok && r.countsAsFailure) {
    const locks = flow.get('guardLockouts') || {};
    const keys = [];
    if (a && a.addr) keys.push('addr:' + a.addr);
    if (g.holder) keys.push('holder:' + g.holder);
    for (const k of keys) {
        const l = locks[k] || { failures: [], until: 0 };
        l.failures = l.failures.filter((t) => t > now - cfg.lockout.windowSeconds * 1000);
        l.failures.push(now);
        if (l.failures.length >= cfg.lockout.maxFailures) {
            l.until = now + cfg.lockout.seconds * 1000;
            l.failures = [];
            locked = true;
            node.log(JSON.stringify({ event: 'guard.lockout.set', key: k.split(':')[0], until: new Date(l.until).toISOString() }));
        }
        locks[k] = l;
    }
    for (const [k, l] of Object.entries(locks)) {
        if (l.until < now && l.failures.every((t) => t <= now - cfg.lockout.windowSeconds * 1000)) delete locks[k];
    }
    flow.set('guardLockouts', locks);
}
node.log(JSON.stringify({ event: 'guard.login.refused', reason: r.reason, counted: r.countsAsFailure, client_id: a && a.appClient }));

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
delete msg.cookies;
msg.payload = { state: 'refused', message: locked ? 'Too many failed attempts. Logins are paused for a while.' : (a ? a.message : 'The login was refused.') };
return msg;

// GET /guard/consent?consent_challenge=... — asks the authorization server
// for the consent request.
// Outputs: 1 = admin API request, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
if (!cfg || !cfg.ok) return fail(503, 'Login unavailable', 'The login service is not configured. Contact the platform administrator.');
const challenge = String((msg.req.query || {}).consent_challenge || '');
if (!/^[A-Za-z0-9._~-]{1,512}$/.test(challenge)) return fail(400, 'Invalid request', 'Start the login again from the application.');
msg._guard = { consentChallenge: challenge };
msg.method = 'GET';
msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/consent?consent_challenge=' + encodeURIComponent(challenge);
msg.headers = { accept: 'application/json' };
msg.payload = '';
return [msg, null];

// Consent request received. The web applications are first-party clients:
// consent is given without a page, the login policy was the gate. The claims
// verified at login (login context) go into the tokens: org_did, roles and
// purpose into the access token and the ID token, name and email into the ID
// token only. Any other client is refused.
// Outputs: 1 = accept (or reject) consent request, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
if (!cfg || !cfg.ok) return fail(503, 'Login unavailable', 'The login service is not configured. Contact the platform administrator.');
const cr = msg.payload;
if (msg.statusCode !== 200 || !cr || typeof cr !== 'object') {
    const expired = msg.statusCode === 404 || msg.statusCode === 410;
    return fail(expired ? 410 : 502, expired ? 'Login request expired' : 'Login unavailable',
        expired ? 'Start the login again from the application.' : 'The authorization server did not answer. Try again later.');
}
const challenge = msg._guard.consentChallenge;
const clientId = cr.client && typeof cr.client.client_id === 'string' ? cr.client.client_id : '';
const ctx = cr.context && typeof cr.context === 'object' ? cr.context : {};
const claims = ctx.claims && typeof ctx.claims === 'object' ? ctx.claims : null;

msg.method = 'PUT';
msg.headers = { 'content-type': 'application/json', accept: 'application/json' };
if (!cfg.firstPartyClients.includes(clientId) || !claims) {
    node.log(JSON.stringify({ event: 'guard.consent.rejected', client_id: clientId, reason: claims ? 'client not first-party' : 'no verified claims' }));
    msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/consent/reject?consent_challenge=' + encodeURIComponent(challenge);
    msg.payload = JSON.stringify({ error: 'access_denied', error_description: 'The wallet login is limited to the platform applications.' });
    return [msg, null];
}
const tokenClaims = { org_did: claims.org_did, roles: claims.roles, purpose: claims.purpose };
msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/consent/accept?consent_challenge=' + encodeURIComponent(challenge);
msg.payload = JSON.stringify({
    grant_scope: Array.isArray(cr.requested_scope) ? cr.requested_scope : [],
    grant_access_token_audience: Array.isArray(cr.requested_access_token_audience) ? cr.requested_access_token_audience : [],
    remember: false,
    session: {
        access_token: tokenClaims,
        id_token: Object.assign({}, tokenClaims, ctx.display && typeof ctx.display === 'object' ? ctx.display : {})
    }
});
return [msg, null];

// GET /guard/logout?logout_challenge=... — ends the guard session: the
// logout request is accepted without a page. Tokens already issued expire on
// their own (5 minutes).
// Outputs: 1 = accept logout request, 2 = error page.
const cfg = global.get('guardConfig');
const fail = (code, title, text) => {
    msg._guardError = { code, title, text };
    return [null, msg];
};
if (!cfg || !cfg.ok) return fail(503, 'Logout unavailable', 'The login service is not configured. Contact the platform administrator.');
const challenge = String((msg.req.query || {}).logout_challenge || '');
if (!/^[A-Za-z0-9._~-]{1,512}$/.test(challenge)) return fail(400, 'Invalid request', 'Log out again from the application.');
msg.method = 'PUT';
msg.url = cfg.hydraAdmin + '/admin/oauth2/auth/requests/logout/accept?logout_challenge=' + encodeURIComponent(challenge);
msg.headers = { accept: 'application/json' };
msg.payload = '';
return [msg, null];

// Reply of the authorization server to an accept or reject call:
// {redirect_to}. Sends the browser there.
// Outputs: 1 = redirect, 2 = error page.
const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
if (msg.statusCode !== 200 || typeof p.redirect_to !== 'string' || !/^https?:\/\//.test(p.redirect_to)) {
    msg._guardError = { code: 502, title: 'Login unavailable', text: 'The authorization server did not answer. Try again later.' };
    return [null, msg];
}
msg.statusCode = 302;
msg.headers = { location: p.redirect_to, 'cache-control': 'no-store' };
delete msg.cookies;
msg.payload = '';
return [msg, null];

// GET /guard/error?error=...&error_description=... — where the authorization
// server sends the browser when it cannot complete a login. Shows its error
// code and description (escaped, shortened) on the plain error page.
// Outputs: 1 = error page.
const q = msg.req.query || {};
const clip = (v, n) => String(v || '').replace(/[\r\n\t]+/g, ' ').slice(0, n);
const code = clip(q.error, 64) || 'unknown_error';
const desc = clip(q.error_description, 300);
msg._guardError = {
    code: 400,
    title: 'Login failed',
    text: (desc ? desc + ' ' : '') + '(' + code + '). Start the login again from the application.'
};
return msg;

// GET /guard/admin/lockouts lists the active lockouts; DELETE
// /guard/admin/lockouts?key=<addr:...|holder:...> lifts one. Bearer
// GUARD_ADMIN_TOKEN, compared in constant time; both actions are audited.
// Without a configured token the endpoints answer 503 (fail closed).
// Exposed inside the cluster only (not routed by the ingress).
// libs: crypto. Outputs: 1 = JSON answer.
const answer = (code, body) => {
    msg.statusCode = code;
    msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
    delete msg.cookies;
    msg.payload = body;
    return msg;
};
const token = String(env.get('GUARD_ADMIN_TOKEN') || '');
if (!token) return answer(503, { error: 'admin endpoints disabled: GUARD_ADMIN_TOKEN is not set' });
const h = String((msg.req.headers || {}).authorization || '');
const given = h.toLowerCase().startsWith('bearer ') ? h.slice(7).trim() : '';
const a = crypto.createHash('sha256').update(given).digest();
const b = crypto.createHash('sha256').update(token).digest();
if (!given || !crypto.timingSafeEqual(a, b)) return answer(401, { error: 'admin token required' });

const now = Date.now();
const locks = flow.get('guardLockouts') || {};
if (msg.req.method === 'DELETE') {
    const key = String((msg.req.query || {}).key || '');
    if (!/^(addr|holder):.{1,512}$/.test(key)) return answer(400, { error: 'key must be addr:<address> or holder:<did>' });
    const existed = Object.prototype.hasOwnProperty.call(locks, key);
    delete locks[key];
    flow.set('guardLockouts', locks);
    node.log(JSON.stringify({ event: 'guard.lockout.lifted', key, existed }));
    return answer(200, { lifted: existed, key });
}
const active = Object.entries(locks)
    .filter(([, l]) => l.until > now)
    .map(([key, l]) => ({ key, until: new Date(l.until).toISOString() }));
node.log(JSON.stringify({ event: 'guard.lockout.listed', count: active.length }));
return answer(200, { lockouts: active });

// GET /guard/health — readiness of the login provider: 200 when the
// configuration is valid, 503 otherwise (the errors name variables, not
// values).
// Outputs: 1 = JSON answer.
const cfg = global.get('guardConfig');
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
delete msg.cookies;
if (cfg && cfg.ok) {
    msg.statusCode = 200;
    msg.payload = { status: 'ok', verifier: cfg.verifier.api };
} else {
    msg.statusCode = 503;
    msg.payload = { status: 'misconfigured', errors: cfg ? cfg.errors : ['configuration not loaded'] };
}
return msg;
